  parameter NUM_SRC   = 8,
  parameter PRIO_BITS = 3
) (
  input                              PCLK,
  input                              PRESETn,
  input                              PSEL,
  input                              PENABLE,
  input                              PWRITE,
  input  [7:0]                       PADDR,
  input  [31:0]                      PWDATA,
  output [31:0]                      PRDATA,
  output                             PREADY,
  output                             PSLVERR,
  input  [NUM_SRC-1:0]               irq_src,
  output                             irq,
  output [$clog2(NUM_SRC+1)-1:0]     irq_id
);
  localparam IDW = $clog2(NUM_SRC + 1);

  wire                     rst = !PRESETn;
  wire                     wr_en, rd_en, err;
  wire [7:0]               addr;
  wire [31:0]              wdata, rdata;
  wire                     gen;
