      A_INSERVICE: rdata[NUM_SRC-1:0] = in_service;
      A_STATUS: begin
        rdata[0]    = irq;
        rdata[15:8] = irq ? irq_id : 8'b0;
      end
      A_ID:        rdata = ID_VALUE;
      default:
        if (is_prio)
          for (j = 0; j < 8; j = j + 1)
            if (prio_word * 8 + j < NUM_SRC)
              rdata[4*j +: PRIO_BITS] = prio_flat[(prio_word*8 + j)*PRIO_BITS +: PRIO_BITS];
    endcase
