      enable     <= 0;
      trigger    <= 0;
      in_service <= 0;
      threshold  <= 0;
      prio_flat  <= 0;
    end else begin
      if (claim)
        in_service[irq_id - 1] <= 1'b1;
      if (do_write) begin
