                dly_cntr <= pwm_dt;
            else
                dly_cntr <= dly_cntr - 1;

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pwm0_delayed <= 0;
        else if (tick && (dly_cntr == 0))
