    mapped    = is_prio;
    read_only = 1'b0;
    case (addr)
      A_CTRL, A_ENABLE, A_TRIGGER, A_PENDING, A_FORCE, A_THRESH, A_CLAIM:
        mapped = 1'b1;
      A_INSERVICE, A_STATUS, A_ID: begin
        mapped    = 1'b1;
        read_only = 1'b1;
      end
      default: ;
    endcase
  end

