          A_ENABLE:  enable    <= wdata[NUM_SRC-1:0];
          A_TRIGGER: trigger   <= wdata[NUM_SRC-1:0];
          A_THRESH:  threshold <= wdata[PRIO_BITS-1:0];
          A_CLAIM:
