          default:
            if (is_prio)
              for (j = 0; j < 8; j = j + 1)
                if (prio_word * 8 + j < NUM_SRC)
                  prio_flat[(prio_word*8 + j)*PRIO_BITS +: PRIO_BITS] <= wdata[4*j +: PRIO_BITS];
        endcase
      end
    end
