      default:
        if (is_prio)
          for (j = 0; j < 8; j = j + 1)
            if (prio_word * 8 + j < NUM_SRC)
              rdata[4*j +: PRIO_BITS] = prio_flat[(prio_word*8 + j)*PRIO_BITS +: PRIO_BITS];
    endcase
  end

  always @(posedge clk) begin
    if (rst) begin
      gen        <= 1'b0;
      enable     <= 0;
      trigger    <= 0;
      in_service <= 0;
      threshold  <= 0;
      prio_flat  <= 0;
    end else begin
