    .best_valid(best_valid), .best_idx(best_idx), .best_prio(best_prio)
  );

  intc_regs #(.NUM_SRC(NUM_SRC), .PRIO_BITS(PRIO_BITS)) u_regs (
    .clk(PCLK), .rst(rst), .wr_en(wr_en), .rd_en(rd_en), .addr(addr), .wdata(wdata),
