      A_STATUS: begin
        rdata[0]    = irq;
        rdata[15:8] = irq ? irq_id : 8'b0;
      end
      A_ID:        rdata = ID_VALUE;
      default:
        if (is_prio)
          for (j = 0; j < 8; j = j + 1)
