module intc_sync #(
  parameter N = 8
) (
  input              clk,
  input              rst,
  input      [N-1:0] d,
  output reg [N-1:0] q
);
  reg [N-1:0] meta;

  always @(posedge clk) begin
    if (rst) begin
      meta <= 0;
      q    <= 0;
    end else begin
      meta <= d;
      q    <= meta;
    end
