  wire [11:0]    pwm0_cfg;
  wire [11:0]    pwm1_cfg;
  wire           pwm0_inv;
  wire           pwm1_inv;
  wire [7:0]     pwm_dt;
  wire [15:0]    pwm_fault_clr;
  wire           pwm_dt_en;
  wire [31:0]    tmr;
  wire           matchx_flag;
  wire           matchy_flag;
  (* keep *) wire timeout_flag;

  // Register Definitions
  wire [31:0] TMR_WIRE;
  assign TMR_WIRE = tmr;

  reg [31:0] RELOAD_REG;
  assign tmr_reload = RELOAD_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) RELOAD_REG <= 0;
    else if (apb_we & (PADDR[15:0] == RELOAD_REG_OFFSET)) RELOAD_REG <= PWDATA;

  reg [PRW-1:0] PR_REG;
  assign prescaler = PR_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) PR_REG <= 'h0;
    else if (apb_we & (PADDR[15:0] == PR_REG_OFFSET)) PR_REG <= PWDATA[PRW-1:0];

  reg [31:0] CMPX_REG;
  assign cmpx = CMPX_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) CMPX_REG <= 0;
    else if (apb_we & (PADDR[15:0] == CMPX_REG_OFFSET)) CMPX_REG <= PWDATA;

  reg [31:0] CMPY_REG;
  assign cmpy = CMPY_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) CMPY_REG <= 0;
    else if (apb_we & (PADDR[15:0] == CMPY_REG_OFFSET)) CMPY_REG <= PWDATA;

  reg [6:0] CTRL_REG;
  assign tmr_en = CTRL_REG[0];
  assign tmr_start = CTRL_REG[1];
  assign pwm0_en = CTRL_REG[2];
  assign pwm1_en = CTRL_REG[3];
  assign pwm_dt_en = CTRL_REG[4];
  assign pwm0_inv = CTRL_REG[5];
  assign pwm1_inv = CTRL_REG[6];
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) CTRL_REG <= 0;
    else if (apb_we & (PADDR[15:0] == CTRL_REG_OFFSET)) CTRL_REG <= PWDATA[6:0];

  reg [2:0] CFG_REG;
  assign tmr_cfg = CFG_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) CFG_REG <= 0;
    else if (apb_we & (PADDR[15:0] == CFG_REG_OFFSET)) CFG_REG <= PWDATA[2:0];

  reg [11:0] PWM0CFG_REG;
  assign pwm0_cfg = PWM0CFG_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) PWM0CFG_REG <= 0;
    else if (apb_we & (PADDR[15:0] == PWM0CFG_REG_OFFSET)) PWM0CFG_REG <= PWDATA[11:0];

  reg [15:0] PWM1CFG_REG;
  assign pwm1_cfg = PWM1CFG_REG[11:0];
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) PWM1CFG_REG <= 0;
    else if (apb_we & (PADDR[15:0] == PWM1CFG_REG_OFFSET)) PWM1CFG_REG <= PWDATA[15:0];

  reg [7:0] PWMDT_REG;
  assign pwm_dt = PWMDT_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) PWMDT_REG <= 0;
    else if (apb_we & (PADDR[15:0] == PWMDT_REG_OFFSET)) PWMDT_REG <= PWDATA[7:0];

  reg [15:0] PWMFC_REG;
  assign pwm_fault_clr = PWMFC_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) PWMFC_REG <= 0;
    else if (apb_we & (PADDR[15:0] == PWMFC_REG_OFFSET)) PWMFC_REG <= PWDATA[15:0];

  localparam GCLK_REG_OFFSET = 16'hFF10;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) GCLK_REG <= 0;
    else if (apb_we & (PADDR[15:0] == GCLK_REG_OFFSET)) GCLK_REG <= PWDATA[0];

  reg  [2:0] IM_REG;
  reg  [2:0] IC_REG;
  reg  [2:0] RIS_REG;

  wire [2:0] MIS_REG = RIS_REG & IM_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) IM_REG <= 0;
    else if (apb_we & (PADDR[15:0] == IM_REG_OFFSET)) IM_REG <= PWDATA[2:0];

  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) IC_REG <= 3'b0;
    else if (apb_we & (PADDR[15:0] == IC_REG_OFFSET)) IC_REG <= PWDATA[2:0];
    else IC_REG <= 3'd0;

  wire [0:0] TO = timeout_flag;
  wire [0:0] MX = matchx_flag;
  wire [0:0] MY = matchy_flag;

  integer _i_;
  always @(posedge PCLK or negedge PRESETn)
    if (!PRESETn) RIS_REG <= 0;
    else begin
      for (_i_ = 0; _i_ < 1; _i_ = _i_ + 1) begin
        if (IC_REG[_i_]) RIS_REG[_i_] <= 1'b0;
        else if (TO[_i_] == 1'b1) RIS_REG[_i_] <= 1'b1;
      end
      for (_i_ = 1; _i_ < 2; _i_ = _i_ + 1) begin
        if (IC_REG[_i_]) RIS_REG[_i_] <= 1'b0;
        else if (MX[_i_-1] == 1'b1) RIS_REG[_i_] <= 1'b1;
      end
      for (_i_ = 2; _i_ < 3; _i_ = _i_ + 1) begin
        if (IC_REG[_i_]) RIS_REG[_i_] <= 1'b0;
        else if (MY[_i_-2] == 1'b1) RIS_REG[_i_] <= 1'b1;
      end
    end

  assign IRQ = |MIS_REG;

  EF_TMR32 #(
      .PRW(PRW)
  ) instance_to_wrap (
      .clk(clk),
      .rst_n(rst_n),
      .tmr_en(tmr_en),
      .tmr_start(tmr_start),
      .pwm0_en(pwm0_en),
      .pwm1_en(pwm1_en),
      .tmr_reload(tmr_reload),
      .cmpx(cmpx),
      .cmpy(cmpy),
      .prescaler(prescaler),
      .tmr_cfg(tmr_cfg),
      .pwm0_cfg(pwm0_cfg),
      .pwm1_cfg(pwm1_cfg),
      .pwm0_inv(pwm0_inv),
      .pwm1_inv(pwm1_inv),
      .pwm_dt(pwm_dt),
      .pwm_fault_clr(pwm_fault_clr),
      .pwm_dt_en(pwm_dt_en),
      .tmr(tmr),
      .matchx_flag(matchx_flag),
      .matchy_flag(matchy_flag),
      .timeout_flag(timeout_flag),
      .pwm0(pwm0),
      .pwm1(pwm1),
      .pwm_fault(pwm_fault)
  );

  assign PRDATA =
      (PADDR[15:0] == TMR_REG_OFFSET)      ? TMR_WIRE :
      (PADDR[15:0] == RELOAD_REG_OFFSET)   ? RELOAD_REG :
      (PADDR[15:0] == PR_REG_OFFSET)      ? PR_REG :
      (PADDR[15:0] == CMPX_REG_OFFSET)    ? CMPX_REG :
      (PADDR[15:0] == CMPY_REG_OFFSET)    ? CMPY_REG :
      (PADDR[15:0] == CTRL_REG_OFFSET)    ? CTRL_REG :
      (PADDR[15:0] == CFG_REG_OFFSET)     ? CFG_REG :
      (PADDR[15:0] == PWM0CFG_REG_OFFSET) ? PWM0CFG_REG :
      (PADDR[15:0] == PWM1CFG_REG_OFFSET) ? PWM1CFG_REG :
      (PADDR[15:0] == PWMDT_REG_OFFSET)   ? PWMDT_REG :
      (PADDR[15:0] == PWMFC_REG_OFFSET)   ? PWMFC_REG :
      (PADDR[15:0] == IM_REG_OFFSET)      ? IM_REG :
      (PADDR[15:0] == MIS_REG_OFFSET)     ? MIS_REG :
      (PADDR[15:0] == RIS_REG_OFFSET)     ? RIS_REG :
      (PADDR[15:0] == GCLK_REG_OFFSET)    ? GCLK_REG :
      32'hDEADBEEF;

  assign PREADY = 1'b1;

endmodule
