`timescale 1ns / 1ps
`default_nettype none

module EF_UART_APB #(
    parameter SC = 8,
    MDW = 9,
    GFLEN = 8,
    FAW = 4
) (
    input  wire         PCLK,
    input  wire         PRESETn,
    input  wire         PWRITE,
    input  wire [ 31:0] PWDATA,
    input  wire [ 31:0] PADDR,
    input  wire         PENABLE,
    input  wire         PSEL,
    output wire         PREADY,
    output wire [ 31:0] PRDATA,
    output wire         IRQ,
    input  wire [1-1:0] rx,
    output wire [1-1:0] tx
);

  localparam RXDATA_REG_OFFSET = 16'h0000;
  localparam TXDATA_REG_OFFSET = 16'h0004;
  localparam PR_REG_OFFSET = 16'h0008;
  localparam CTRL_REG_OFFSET = 16'h000C;
  localparam CFG_REG_OFFSET = 16'h0010;
  localparam MATCH_REG_OFFSET = 16'h001C;
  localparam RX_FIFO_LEVEL_REG_OFFSET = 16'hFE00;
  localparam RX_FIFO_THRESHOLD_REG_OFFSET = 16'hFE04;
  localparam RX_FIFO_FLUSH_REG_OFFSET = 16'hFE08;
  localparam TX_FIFO_LEVEL_REG_OFFSET = 16'hFE10;
  localparam TX_FIFO_THRESHOLD_REG_OFFSET = 16'hFE14;
  localparam TX_FIFO_FLUSH_REG_OFFSET = 16'hFE18;
  localparam IM_REG_OFFSET = 16'hFF00;
  localparam MIS_REG_OFFSET = 16'hFF04;
  localparam RIS_REG_OFFSET = 16'hFF08;
  localparam IC_REG_OFFSET = 16'hFF0C;

  reg [0:0] GCLK_REG;

  wire           clk = PCLK;
  wire           rst_n = PRESETn;

  wire           apb_valid = PSEL & PENABLE;
  wire           apb_we = PWRITE & apb_valid;
  wire           apb_re = ~PWRITE & apb_valid;

  wire [ 16-1:0] prescaler;
  wire [  1-1:0] en;
  wire [  1-1:0] tx_en;
  wire [  1-1:0] rx_en;
  wire [MDW-1:0] wdata;
  wire [  6-1:0] timeout_bits;
  wire [  1-1:0] loopback_en;
  wire [  1-1:0] glitch_filter_en;
  wire [FAW-1:0] tx_level;
  wire [FAW-1:0] rx_level;
  wire [  1-1:0] rd;
  wire [  1-1:0] wr;
  wire [  1-1:0] tx_fifo_flush;
  wire [  1-1:0] rx_fifo_flush;
  wire [  4-1:0] data_size;
  wire [  1-1:0] stop_bits_count;
  wire [  3-1:0] parity_type;
  wire [FAW-1:0] txfifotr;
  wire [FAW-1:0] rxfifotr;
  wire [MDW-1:0] match_data;
  wire [  1-1:0] tx_empty;
  wire [  1-1:0] tx_full;
  wire [  1-1:0] tx_level_below;
  wire [MDW-1:0] rdata;
  wire [  1-1:0] rx_empty;
  wire [  1-1:0] rx_full;
  wire [  1-1:0] rx_level_above;
  wire [  1-1:0] break_flag;
  wire [  1-1:0] match_flag;
  wire [  1-1:0] frame_error_flag;
  wire [  1-1:0] parity_error_flag;
  wire [  1-1:0] overrun_flag;
  wire [  1-1:0] timeout_flag;

  wire [MDW-1:0] RXDATA_WIRE;

  reg  [15:0] PR_REG;
  assign prescaler = PR_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn) PR_REG <= 0;
    else if (apb_we & (PADDR[15:0] == 16'h0008)) PR_REG <= PWDATA[15:0];

  reg [4:0] CTRL_REG;
  assign en = CTRL_REG[0:0];
  assign tx_en = CTRL_REG[1:1];
  assign rx_en = CTRL_REG[2:2];
  assign loopback_en = CTRL_REG[3:3];
  assign glitch_filter_en = CTRL_REG[4:4];
  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn) CTRL_REG <= 0;
    else if (apb_we & (PADDR[15:0] == CTRL_REG_OFFSET)) CTRL_REG <= PWDATA[4:0];

  reg [13:0] CFG_REG;
  assign data_size = CFG_REG[3:0];
  assign stop_bits_count = CFG_REG[4:4];
  assign parity_type = CFG_REG[7:5];
  assign timeout_bits = CFG_REG[13:8];
  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn) CFG_REG <= 'h3F08;
    else if (apb_we & (PADDR[15:0] == CFG_REG_OFFSET)) CFG_REG <= PWDATA[13:0];

  reg [MDW-1:0] MATCH_REG;
  assign match_data = MATCH_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn) MATCH_REG <= 0;
    else if (apb_we & (PADDR[15:0] == MATCH_REG_OFFSET)) MATCH_REG <= PWDATA[MDW-1:0];

  wire [FAW-1:0] RX_FIFO_LEVEL_WIRE;
  assign RX_FIFO_LEVEL_WIRE = rx_level;

  reg [FAW-1:0] RX_FIFO_THRESHOLD_REG;
  assign rxfifotr = RX_FIFO_THRESHOLD_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn) RX_FIFO_THRESHOLD_REG <= 0;
    else if (apb_we & (PADDR[15:0] == RX_FIFO_THRESHOLD_REG_OFFSET))
      RX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];

  reg [0:0] RX_FIFO_FLUSH_REG;
  assign rx_fifo_flush = RX_FIFO_FLUSH_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn) RX_FIFO_FLUSH_REG <= 0;
    else if (apb_we & (PADDR[15:0] == RX_FIFO_FLUSH_REG_OFFSET))
      RX_FIFO_FLUSH_REG <= PWDATA[0:0];
    else RX_FIFO_FLUSH_REG <= 1'b0;

  wire [FAW-1:0] TX_FIFO_LEVEL_WIRE;
  assign TX_FIFO_LEVEL_WIRE = tx_level;

  reg [FAW-1:0] TX_FIFO_THRESHOLD_REG;
  assign txfifotr = TX_FIFO_THRESHOLD_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn) TX_FIFO_THRESHOLD_REG <= 0;
    else if (apb_we & (PADDR[15:0] == TX_FIFO_THRESHOLD_REG_OFFSET))
      TX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];

  reg [0:0] TX_FIFO_FLUSH_REG;
  assign tx_fifo_flush = TX_FIFO_FLUSH_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn) TX_FIFO_FLUSH_REG <= 0;
    else if (apb_we & (PADDR[15:0] == TX_FIFO_FLUSH_REG_OFFSET))
      TX_FIFO_FLUSH_REG <= PWDATA[0:0];
    else TX_FIFO_FLUSH_REG <= 1'b0;

  localparam GCLK_REG_OFFSET = 16'hFF10;
  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn) GCLK_REG <= 0;
    else if (apb_we & (PADDR[15:0] == GCLK_REG_OFFSET)) GCLK_REG <= PWDATA[0:0];

  reg  [9:0] IM_REG;
  reg  [9:0] IC_REG;
  reg  [9:0] RIS_REG;

  wire [9:0] MIS_REG = RIS_REG & IM_REG;
  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn) IM_REG <= 0;
    else if (apb_we & (PADDR[15:0] == IM_REG_OFFSET)) IM_REG <= PWDATA[9:0];
  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn) IC_REG <= 10'b0;
    else if (apb_we & (PADDR[15:0] == IC_REG_OFFSET)) IC_REG <= PWDATA[9:0];
    else IC_REG <= 10'd0;

  wire TXE = tx_empty;
  wire RXF = rx_full;
  wire TXB = tx_level_below;
  wire RXA = rx_level_above;
  wire BRK = break_flag;
  wire MATCH = match_flag;
  wire FE = frame_error_flag;
  wire PRE = parity_error_flag;
  wire OR = overrun_flag;
  wire RTO = timeout_flag;

  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn) RIS_REG <= 10'b0;
    else begin
      if (IC_REG[0]) RIS_REG[0] <= 1'b0;
      else if (TXE) RIS_REG[0] <= 1'b1;

      if (IC_REG[1]) RIS_REG[1] <= 1'b0;
      else if (RXF) RIS_REG[1] <= 1'b1;

      if (IC_REG[2]) RIS_REG[2] <= 1'b0;
      else if (TXB) RIS_REG[2] <= 1'b1;

      if (IC_REG[3]) RIS_REG[3] <= 1'b0;
      else if (RXA) RIS_REG[3] <= 1'b1;

      if (IC_REG[4]) RIS_REG[4] <= 1'b0;
      else if (BRK) RIS_REG[4] <= 1'b1;

      if (IC_REG[5]) RIS_REG[5] <= 1'b0;
      else if (MATCH) RIS_REG[5] <= 1'b1;

      if (IC_REG[6]) RIS_REG[6] <= 1'b0;
      else if (FE) RIS_REG[6] <= 1'b1;

      if (IC_REG[7]) RIS_REG[7] <= 1'b0;
      else if (PRE) RIS_REG[7] <= 1'b1;

      if (IC_REG[8]) RIS_REG[8] <= 1'b0;
      else if (OR) RIS_REG[8] <= 1'b1;

      if (IC_REG[9]) RIS_REG[9] <= 1'b0;
      else if (RTO) RIS_REG[9] <= 1'b1;
    end

  assign IRQ = |MIS_REG;

  EF_UART #(
      .SC(SC),
      .MDW(MDW),
      .GFLEN(GFLEN),
      .FAW(FAW)
  ) instance_to_wrap (
      .clk(clk),
      .rst_n(rst_n),
      .prescaler(prescaler),
      .en(en),
      .tx_en(tx_en),
      .rx_en(rx_en),
      .wdata(wdata),
      .timeout_bits(timeout_bits),
      .loopback_en(loopback_en),
      .glitch_filter_en(glitch_filter_en),
      .tx_level(tx_level),
      .rx_level(rx_level),
      .rd(rd),
      .wr(wr),
      .tx_fifo_flush(tx_fifo_flush),
      .rx_fifo_flush(rx_fifo_flush),
      .data_size(data_size),
      .stop_bits_count(stop_bits_count),
      .parity_type(parity_type),
      .txfifotr(txfifotr),
      .rxfifotr(rxfifotr),
      .match_data(match_data),
      .tx_empty(tx_empty),
      .tx_full(tx_full),
      .tx_level_below(tx_level_below),
      .rdata(rdata),
      .rx_empty(rx_empty),
      .rx_full(rx_full),
      .rx_level_above(rx_level_above),
      .break_flag(break_flag),
      .match_flag(match_flag),
      .frame_error_flag(frame_error_flag),
      .parity_error_flag(parity_error_flag),
      .overrun_flag(overrun_flag),
      .timeout_flag(timeout_flag),
      .rx(rx),
      .tx(tx)
  );

  assign PRDATA =
      (PADDR[15:0] == RXDATA_REG_OFFSET) ? RXDATA_WIRE :
      (PADDR[15:0] == PR_REG_OFFSET) ? PR_REG :
      (PADDR[15:0] == CTRL_REG_OFFSET) ? CTRL_REG :
      (PADDR[15:0] == CFG_REG_OFFSET) ? CFG_REG :
      (PADDR[15:0] == MATCH_REG_OFFSET) ? MATCH_REG :
      (PADDR[15:0] == RX_FIFO_LEVEL_REG_OFFSET) ? RX_FIFO_LEVEL_WIRE :
      (PADDR[15:0] == RX_FIFO_THRESHOLD_REG_OFFSET) ? RX_FIFO_THRESHOLD_REG :
      (PADDR[15:0] == RX_FIFO_FLUSH_REG_OFFSET) ? RX_FIFO_FLUSH_REG :
      (PADDR[15:0] == TX_FIFO_LEVEL_REG_OFFSET) ? TX_FIFO_LEVEL_WIRE :
      (PADDR[15:0] == TX_FIFO_THRESHOLD_REG_OFFSET) ? TX_FIFO_THRESHOLD_REG :
      (PADDR[15:0] == TX_FIFO_FLUSH_REG_OFFSET) ? TX_FIFO_FLUSH_REG :
      (PADDR[15:0] == IM_REG_OFFSET) ? IM_REG :
      (PADDR[15:0] == MIS_REG_OFFSET) ? MIS_REG :
      (PADDR[15:0] == RIS_REG_OFFSET) ? RIS_REG :
      (PADDR[15:0] == GCLK_REG_OFFSET) ? GCLK_REG :
      32'hDEADBEEF;

  assign PREADY = 1'b1;

  assign RXDATA_WIRE = rdata;
  assign rd = (apb_re & (PADDR[15:0] == RXDATA_REG_OFFSET));
  assign wdata = PWDATA;
  assign wr = (apb_we & (PADDR[15:0] == TXDATA_REG_OFFSET));
endmodule
