    localparam RXDATA_REG_OFFSET = 16'h0000;
    localparam TXDATA_REG_OFFSET = 16'h0004;
    localparam PR_REG_OFFSET = 16'h0008;
    localparam CTRL_REG_OFFSET = 16'h000C;
    localparam CFG_REG_OFFSET = 16'h0010;
    localparam MATCH_REG_OFFSET = 16'h001C;
    localparam RX_FIFO_LEVEL_REG_OFFSET = 16'hFE00;
    localparam RX_FIFO_THRESHOLD_REG_OFFSET = 16'hFE04;
    localparam RX_FIFO_FLUSH_REG_OFFSET = 16'hFE08;
    localparam TX_FIFO_LEVEL_REG_OFFSET = 16'hFE10;
    localparam TX_FIFO_THRESHOLD_REG_OFFSET = 16'hFE14;
    localparam TX_FIFO_FLUSH_REG_OFFSET = 16'hFE18;
    localparam IM_REG_OFFSET = 16'hFF00;
    localparam MIS_REG_OFFSET = 16'hFF04;
    localparam RIS_REG_OFFSET = 16'hFF08;
    localparam IC_REG_OFFSET = 16'hFF0C;
    localparam GCLK_REG_OFFSET = 16'hFF10;

    reg [0:0] GCLK_REG;
    wire clk = PCLK;
    wire rst_n = PRESETn;

    wire apb_valid = PSEL & PENABLE;
    wire apb_we = PWRITE & apb_valid;
    wire apb_re = ~PWRITE & apb_valid;

    wire [15:0] prescaler;
    wire en;
    wire tx_en;
    wire rx_en;
    wire [MDW-1:0] wdata;
    wire [5:0] timeout_bits;
    wire loopback_en;
    wire glitch_filter_en;
    wire [FAW-1:0] tx_level;
    wire [FAW-1:0] rx_level;
    wire rd;
    wire wr;
    wire tx_fifo_flush;
    wire rx_fifo_flush;
    wire [3:0] data_size;
    wire stop_bits_count;
    wire [2:0] parity_type;
    wire [FAW-1:0] txfifotr;
    wire [FAW-1:0] rxfifotr;
    wire [MDW-1:0] match_data;
    wire tx_empty;
    wire tx_full;
    wire tx_level_below;
    wire [MDW-1:0] rdata;
    wire rx_empty;
    wire rx_full;
    wire rx_level_above;
    wire break_flag;
    wire match_flag;
    wire frame_error_flag;
    wire parity_error_flag;
    wire overrun_flag;
    wire timeout_flag;

    reg [15:0] PR_REG;
    assign prescaler = PR_REG;
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) PR_REG <= 0;
        else if(apb_we & (PADDR[15:0] == PR_REG_OFFSET))
            PR_REG <= PWDATA[15:0];

    reg [4:0] CTRL_REG;
    assign en = CTRL_REG[0];
    assign tx_en = CTRL_REG[1];
    assign rx_en = CTRL_REG[2];
    assign loopback_en = CTRL_REG[3];
    assign glitch_filter_en = CTRL_REG[4];
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) CTRL_REG <= 0;
        else if(apb_we & (PADDR[15:0] == CTRL_REG_OFFSET))
            CTRL_REG <= PWDATA[4:0];

    reg [13:0] CFG_REG;
    assign data_size = CFG_REG[3:0];
    assign stop_bits_count = CFG_REG[4];
    assign parity_type = CFG_REG[7:5];
    assign timeout_bits = CFG_REG[13:8];
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) CFG_REG <= 14'h3F08;
        else if(apb_we & (PADDR[15:0] == CFG_REG_OFFSET))
            CFG_REG <= PWDATA[13:0];

    reg [MDW-1:0] MATCH_REG;
    assign match_data = MATCH_REG;
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) MATCH_REG <= 0;
        else if(apb_we & (PADDR[15:0] == MATCH_REG_OFFSET))
            MATCH_REG <= PWDATA[MDW-1:0];

    reg [FAW-1:0] RX_FIFO_THRESHOLD_REG;
    assign rxfifotr = RX_FIFO_THRESHOLD_REG;
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) RX_FIFO_THRESHOLD_REG <= 0;
        else if(apb_we & (PADDR[15:0] == RX_FIFO_THRESHOLD_REG_OFFSET))
            RX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];

    reg RX_FIFO_FLUSH_REG;
    assign rx_fifo_flush = RX_FIFO_FLUSH_REG;
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) RX_FIFO_FLUSH_REG <= 0;
        else if(apb_we & (PADDR[15:0] == RX_FIFO_FLUSH_REG_OFFSET))
            RX_FIFO_FLUSH_REG <= PWDATA[0];
        else
            RX_FIFO_FLUSH_REG <= 1'b0;

    reg [FAW-1:0] TX_FIFO_THRESHOLD_REG;
    assign txfifotr = TX_FIFO_THRESHOLD_REG;
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) TX_FIFO_THRESHOLD_REG <= 0;
        else if(apb_we & (PADDR[15:0] == TX_FIFO_THRESHOLD_REG_OFFSET))
            TX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];

    reg TX_FIFO_FLUSH_REG;
    assign tx_fifo_flush = TX_FIFO_FLUSH_REG;
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) TX_FIFO_FLUSH_REG <= 0;
        else if(apb_we & (PADDR[15:0] == TX_FIFO_FLUSH_REG_OFFSET))
            TX_FIFO_FLUSH_REG <= PWDATA[0];
        else
            TX_FIFO_FLUSH_REG <= 1'b0;

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) GCLK_REG <= 0;
        else if(apb_we & (PADDR[15:0] == GCLK_REG_OFFSET))
            GCLK_REG <= PWDATA[0];

    reg [9:0] IM_REG;
    reg [9:0] IC_REG;
    reg [9:0] RIS_REG;

    wire [9:0] MIS_REG = RIS_REG & IM_REG;

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) IM_REG <= 0;
        else if(apb_we & (PADDR[15:0] == IM_REG_OFFSET))
            IM_REG <= PWDATA[9:0];

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) IC_REG <= 10'b0;
        else if(apb_we & (PADDR[15:0] == IC_REG_OFFSET))
            IC_REG <= PWDATA[9:0];
        else
            IC_REG <= 10'd0;

    wire [9:0] irq_conditions = {
        timeout_flag,
        overrun_flag,
        parity_error_flag,
        frame_error_flag,
        match_flag,
        break_flag,
        rx_level_above,
        tx_level_below,
        rx_full,
        tx_empty
    };

    integer i;
    always @(posedge PCLK or negedge PRESETn) begin
        if(!PRESETn)
            RIS_REG <= 10'b0;
        else
            for(i = 0; i < 10; i = i + 1) begin
                if(IC_REG[i])
                    RIS_REG[i] <= 1'b0;
                else if(irq_conditions[i])
                    RIS_REG[i] <= 1'b1;
            end
    end

    assign IRQ = |MIS_REG;

    EF_UART #(
        .SC(SC),
        .MDW(MDW),
        .GFLEN(GFLEN),
        .FAW(FAW)
    ) instance_to_wrap (
        .clk(clk),
        .rst_n(rst_n),
        .prescaler(prescaler),
        .en(en),
        .tx_en(tx_en),
        .rx_en(rx_en),
        .wdata(wdata),
        .timeout_bits(timeout_bits),
        .loopback_en(loopback_en),
        .glitch_filter_en(glitch_filter_en),
        .tx_level(tx_level),
        .rx_level(rx_level),
        .rd(rd),
        .wr(wr),
        .tx_fifo_flush(tx_fifo_flush),
        .rx_fifo_flush(rx_fifo_flush),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .txfifotr(txfifotr),
        .rxfifotr(rxfifotr),
        .match_data(match_data),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level_below(tx_level_below),
        .rdata(rdata),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

    assign PRDATA =
        (PADDR[15:0] == RXDATA_REG_OFFSET) ? rdata :
        (PADDR[15:0] == PR_REG_OFFSET) ? PR_REG :
        (PADDR[15:0] == CTRL_REG_OFFSET) ? CTRL_REG :
        (PADDR[15:0] == CFG_REG_OFFSET) ? CFG_REG :
        (PADDR[15:0] == MATCH_REG_OFFSET) ? MATCH_REG :
        (PADDR[15:0] == RX_FIFO_LEVEL_REG_OFFSET) ? rx_level :
        (PADDR[15:0] == RX_FIFO_THRESHOLD_REG_OFFSET) ? RX_FIFO_THRESHOLD_REG :
        (PADDR[15:0] == RX_FIFO_FLUSH_REG_OFFSET) ? RX_FIFO_FLUSH_REG :
        (PADDR[15:0] == TX_FIFO_LEVEL_REG_OFFSET) ? tx_level :
        (PADDR[15:0] == TX_FIFO_THRESHOLD_REG_OFFSET) ? TX_FIFO_THRESHOLD_REG :
        (PADDR[15:0] == TX_FIFO_FLUSH_REG_OFFSET) ? TX_FIFO_FLUSH_REG :
        (PADDR[15:0] == IM_REG_OFFSET) ? IM_REG :
        (PADDR[15:0] == MIS_REG_OFFSET) ? MIS_REG :
        (PADDR[15:0] == RIS_REG_OFFSET) ? RIS_REG :
        (PADDR[15:0] == GCLK_REG_OFFSET) ? GCLK_REG :
        32'hDEADBEEF;

    assign PREADY = 1'b1;
    assign rd = apb_re & (PADDR[15:0] == RXDATA_REG_OFFSET);
    assign wdata = PWDATA[MDW-1:0];
    assign wr = apb_we & (PADDR[15:0] == TXDATA_REG_OFFSET);

