    input   wire            rst_n,

    input   wire [15:0]     prescaler,
    input   wire            en,
    input   wire            tx_en,
    input   wire            rx_en,
    input   wire            rd,
    input   wire            wr,
    input   wire [MDW-1:0]  wdata,
    input   wire [3:0]      data_size,
    input   wire            stop_bits_count,
    input   wire [2:0]      parity_type,
    input   wire [3:0]      txfifotr,
    input   wire [3:0]      rxfifotr,
    input   wire [MDW-1:0]  match_data,
    input   wire [5:0]      timeout_bits,
    input   wire            loopback_en,
    input   wire            glitch_filter_en,
    input   wire            tx_fifo_flush,
    input   wire            rx_fifo_flush,

    output  wire            tx_empty,
    output  wire            tx_full,
    output  wire [FAW-1:0]  tx_level,
    output  wire            tx_level_below,
    output  wire [MDW-1:0]  rdata,
    output  wire            rx_empty,
    output  wire            rx_full,
    output  wire [FAW-1:0]  rx_level,
    output  wire            rx_level_above,

    output  wire            break_flag,
    output  wire            match_flag,
    output  wire            frame_error_flag,
    output  wire            parity_error_flag,
    output  wire            overrun_flag,
    output  wire            timeout_flag,

    input   wire            rx,
    output  wire            tx
);

    wire tx_done;
    wire rx_done;
    wire b_tick;

    wire [MDW-1:0] tx_data;
    wire [MDW-1:0] rx_data;

    wire rx_synched;
    wire rx_filtered;
    wire rx_in;

    ef_util_sync rx_sync (
        .clk(clk),
        .in(rx),
        .out(rx_synched)
    );

    ef_util_glitch_filter #(.N(GFLEN)) rx_glitch_filter (
        .clk(clk),
        .rst_n(rst_n),
        .en(glitch_filter_en),
        .in(rx_synched),
        .out(rx_filtered)
    );

    assign rx_in = loopback_en ? tx :
                   glitch_filter_en ? rx_filtered :
                   rx_synched;

    BAUDGEN baud_gen (
        .clk(clk),
        .rst_n(rst_n),
        .prescale(prescaler),
        .en(en),
        .baudtick(b_tick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) fifo_tx (
        .clk(clk),
        .rst_n(rst_n),
        .rd(tx_done),
        .wr(wr),
        .wdata(wdata),
        .empty(tx_empty),
        .full(tx_full),
        .rdata(tx_data),
        .level(tx_level),
        .flush(tx_fifo_flush)
    );

    UART_TX #(.MDW(MDW), .NUM_SAMPLES(SC)) uart_tx (
        .clk(clk),
        .resetn(rst_n),
        .tx_start(~tx_empty),
        .b_tick(b_tick & tx_en),
        .data_size(data_size),
        .parity_type(parity_type),
        .stop_bits_count(stop_bits_count),
        .d_in(tx_data),
        .tx_done(tx_done),
        .tx(tx)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) fifo_rx (
        .clk(clk),
        .rst_n(rst_n),
        .rd(rd),
        .wr(rx_done),
        .wdata(rx_data),
        .empty(rx_empty),
        .full(rx_full),
        .rdata(rdata),
        .level(rx_level),
        .flush(rx_fifo_flush)
    );

    UART_RX #(.MDW(MDW), .NUM_SAMPLES(SC)) uart_rx (
        .clk(clk),
        .resetn(rst_n),
        .b_tick(b_tick & rx_en),
        .data_size(data_size),
        .parity_type(parity_type),
        .stop_bits_count(stop_bits_count),
        .match_data(match_data),
        .rx(rx_in),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .rx_done(rx_done),
        .dout(rx_data)
    );

    localparam SAMPLE_COUNT_WIDTH = (SC < 2) ? 1 : $clog2(SC);
    reg [5:0] bits_count;
    reg [SAMPLE_COUNT_WIDTH-1:0] samples_count;

    always @(posedge clk, negedge rst_n) begin
        if(!rst_n) begin
            bits_count <= 0;
            samples_count <= 0;
        end else if(b_tick) begin
            if(rx_done)
                bits_count <= 0;
            else if(samples_count == (SC - 1)) begin
                samples_count <= 0;
                if(timeout_flag)
                    bits_count <= 0;
                else
                    bits_count <= bits_count + 1'b1;
            end else
                samples_count <= samples_count + 1'b1;
        end
    end

    assign tx_level_below = (tx_level < txfifotr) & ~tx_full;
    assign rx_level_above = (rx_level > rxfifotr) | rx_full;
    assign overrun_flag = rx_full & rx_done;
    assign timeout_flag = (bits_count == timeout_bits);

endmodule

module BAUDGEN (
    input   wire        clk,
    input   wire        rst_n,
    input   wire [15:0] prescale,
    input   wire        en,
    output  wire        baudtick
);

    reg [15:0] count_reg;
    wire [15:0] count_next;

    always @(posedge clk, negedge rst_n) begin
        if(!rst_n)
            count_reg <= 0;
        else if(en)
            count_reg <= count_next;
    end

    assign count_next = (count_reg == prescale) ? 16'd0 : count_reg + 1'b1;
    assign baudtick = (count_reg == prescale);

endmodule

/*
    UART Receiver
*/
module UART_RX #(parameter NUM_SAMPLES = 16, MDW = 8)(
    input   wire            clk,
    input   wire            resetn,
    input   wire            b_tick,
    input   wire [3:0]      data_size,
    input   wire            stop_bits_count,
    input   wire [2:0]      parity_type,
    input   wire            rx,
    input   wire [MDW-1:0]  match_data,
    output  reg             rx_done,
    output  wire            parity_error,
    output  wire            frame_error,
    output  wire            break_flag,
    output  wire            match_flag,
    output  wire [MDW-1:0]  dout
);

    localparam [2:0] idle_st    = 3'b000;
    localparam [2:0] start_st   = 3'b001;
    localparam [2:0] data_st    = 3'b010;
    localparam [2:0] parity_st  = 3'b011;
    localparam [2:0] stop0_st   = 3'b100;
    localparam [2:0] stop1_st   = 3'b101;

    localparam BAUD_COUNT_WIDTH = (NUM_SAMPLES < 2) ? 1 : $clog2(NUM_SAMPLES + 1);

    reg [2:0] current_state;
    reg [2:0] next_state;
    reg [BAUD_COUNT_WIDTH-1:0] b_reg;
    reg [BAUD_COUNT_WIDTH-1:0] b_next;
    reg [3:0] count_reg;
    reg [3:0] count_next;
    reg [MDW-1:0] data_reg;
    reg [MDW-1:0] data_next;
    reg p_error_reg;
    reg p_error_next;
    reg f_error_reg;
    reg f_error_next;

    always @(posedge clk, negedge resetn) begin
        if(!resetn) begin
            current_state <= idle_st;
            b_reg <= 0;
            count_reg <= 0;
            data_reg <= 0;
            p_error_reg <= 0;
            f_error_reg <= 0;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;

            if(current_state == idle_st)
                p_error_reg <= 0;
            else if(p_error_next)
                p_error_reg <= 1'b1;

            if(current_state == idle_st)
                f_error_reg <= 0;
            else if(f_error_next)
                f_error_reg <= 1'b1;
        end
    end

    always @* begin
        next_state = current_state;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        rx_done = 1'b0;
        p_error_next = 1'b0;
        f_error_next = 1'b0;

        case(current_state)
            idle_st:
                if(~rx & b_tick) begin
                    next_state = start_st;
                    b_next = 0;
                end

            start_st:
                if(b_tick)
                    if(b_reg == (NUM_SAMPLES/2 - 1)) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;

            data_st:
                if(b_tick)
                    if(b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        data_next = {rx, data_reg[MDW-1:1]};
                        if(count_reg == (data_size - 1)) begin
                            if(parity_type == 3'b000)
                                next_state = stop0_st;
                            else
                                next_state = parity_st;
                        end else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;

            parity_st:
                if(b_tick)
                    if(b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        next_state = stop0_st;
                        case(parity_type)
                            3'b001:
                                if((~^dout) != rx) p_error_next = 1'b1;
                            3'b010:
                                if((^dout) != rx) p_error_next = 1'b1;
                            3'b100:
                                if(1'b0 != rx) p_error_next = 1'b1;
                            3'b101:
                                if(1'b1 != rx) p_error_next = 1'b1;
                            default:
                                p_error_next = 1'b0;
                        endcase
                    end else
                        b_next = b_reg + 1'b1;

            stop0_st:
                if(b_tick)
                    if(b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        if(stop_bits_count && !rx)
                            f_error_next = 1'b1;
                        if(stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            rx_done = 1'b1;
                        end
                    end else
                        b_next = b_reg + 1'b1;

            stop1_st:
                if(b_tick)
                    if(b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        next_state = idle_st;
                        rx_done = 1'b1;
                    end else
                        b_next = b_reg + 1'b1;

            default: begin
                next_state = idle_st;
                b_next = 0;
            end
        endcase
    end

    reg [11:0] brk;
    always @(posedge clk, negedge resetn) begin
        if(!resetn)
            brk <= 12'hFFF;
        else if(b_tick)
            if(b_reg == (NUM_SAMPLES - 1)) begin
                if(current_state == idle_st)
                    brk <= 12'hFFF;
                else
                    brk <= {brk[10:0], rx};
            end
    end

    assign dout = data_reg >> (MDW - data_size);
    assign parity_error = p_error_reg & rx_done;
    assign frame_error = f_error_reg & rx_done;
    assign break_flag = (brk == 0);
    assign match_flag = (match_data == dout) & rx_done;

endmodule

/*
    UART Transmitter
*/
module UART_TX #(parameter NUM_SAMPLES = 16, MDW = 8)(
    input   wire                clk,
    input   wire                resetn,
    input   wire                tx_start,
    input   wire                b_tick,
    input   wire [3:0]          data_size,
    input   wire                stop_bits_count,
    input   wire [2:0]          parity_type,
    input   wire [MDW-1:0]      d_in,
    output  reg                 tx_done,
    output  wire                tx
);

    localparam [2:0] idle_st    = 3'b000;
    localparam [2:0] start_st   = 3'b001;
    localparam [2:0] data_st    = 3'b010;
    localparam [2:0] parity_st  = 3'b011;
    localparam [2:0] stop0_st   = 3'b100;
    localparam [2:0] stop1_st   = 3'b101;

    localparam BAUD_COUNT_WIDTH = (NUM_SAMPLES < 2) ? 1 : $clog2(NUM_SAMPLES + 1);

    reg [2:0] current_state;
    reg [2:0] next_state;
    reg [BAUD_COUNT_WIDTH-1:0] b_reg;
    reg [BAUD_COUNT_WIDTH-1:0] b_next;
    reg [3:0] count_reg;
    reg [3:0] count_next;
    reg [MDW-1:0] data_reg;
    reg [MDW-1:0] data_next;
    reg tx_reg;
    reg tx_next;

    wire [MDW-1:0] pdata = d_in & ~({MDW{1'b1}} << data_size);

    always @(posedge clk, negedge resetn) begin
        if(!resetn) begin
            current_state <= idle_st;
            b_reg <= 0;
            count_reg <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
        end else begin
            current_state <= next_state;
            b_reg <= b_next;
            count_reg <= count_next;
            data_reg <= data_next;
            tx_reg <= tx_next;
        end
    end

    always @* begin
        next_state = current_state;
        tx_done = 1'b0;
        b_next = b_reg;
        count_next = count_reg;
        data_next = data_reg;
        tx_next = tx_reg;

        case(current_state)
            idle_st: begin
                tx_next = 1'b1;
                if(tx_start) begin
                    next_state = start_st;
                    b_next = 0;
                    data_next = d_in;
                end
            end

            start_st: begin
                tx_next = 1'b0;
                if(b_tick)
                    if(b_reg == NUM_SAMPLES) begin
                        next_state = data_st;
                        b_next = 0;
                        count_next = 0;
                    end else
                        b_next = b_reg + 1'b1;
            end

            data_st: begin
                tx_next = data_reg[0];
                if(b_tick)
                    if(b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        data_next = data_reg >> 1;
                        if(count_reg == (data_size - 1)) begin
                            if(parity_type == 3'b000)
                                next_state = stop0_st;
                            else
                                next_state = parity_st;
                        end else
                            count_next = count_reg + 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
            end

            parity_st: begin
                tx_next = 1'b0;
                case(parity_type)
                    3'b001: tx_next = ~^pdata;
                    3'b010: tx_next = ^pdata;
                    3'b100: tx_next = 1'b0;
                    3'b101: tx_next = 1'b1;
                    default: tx_next = 1'b0;
                endcase
                if(b_tick)
                    if(b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        next_state = stop0_st;
                    end else
                        b_next = b_reg + 1'b1;
            end

            stop0_st: begin
                tx_next = 1'b1;
                if(b_tick)
                    if(b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        if(stop_bits_count)
                            next_state = stop1_st;
                        else begin
                            next_state = idle_st;
                            tx_done = 1'b1;
                        end
                    end else
                        b_next = b_reg + 1'b1;
            end

            stop1_st: begin
                tx_next = 1'b1;
                if(b_tick)
                    if(b_reg == (NUM_SAMPLES - 1)) begin
                        b_next = 0;
                        next_state = idle_st;
                        tx_done = 1'b1;
                    end else
                        b_next = b_reg + 1'b1;
            end

            default: begin
                next_state = idle_st;
                tx_next = 1'b1;
                b_next = 0;
            end
        endcase
    end

    assign tx = tx_reg;

endmodule

module EF_UART_APB #(
    parameter SC = 8,
    MDW = 9,
    GFLEN = 8,
    FAW = 4
) (
    input  wire         PCLK,
    input  wire         PRESETn,
    input  wire         PWRITE,
    input  wire [31:0]  PWDATA,
    input  wire [31:0]  PADDR,
    input  wire         PENABLE,
    input  wire         PSEL,
    output wire         PREADY,
    output wire [31:0]  PRDATA,
    output wire         IRQ,
    input  wire         rx,
    output wire         tx
);

    localparam RXDATA_REG_OFFSET = 16'h0000;
    localparam TXDATA_REG_OFFSET = 16'h0004;
    localparam PR_REG_OFFSET = 16'h0008;
    localparam CTRL_REG_OFFSET = 16'h000C;
    localparam CFG_REG_OFFSET = 16'h0010;
    localparam MATCH_REG_OFFSET = 16'h001C;
    localparam RX_FIFO_LEVEL_REG_OFFSET = 16'hFE00;
    localparam RX_FIFO_THRESHOLD_REG_OFFSET = 16'hFE04;
    localparam RX_FIFO_FLUSH_REG_OFFSET = 16'hFE08;
    localparam TX_FIFO_LEVEL_REG_OFFSET = 16'hFE10;
    localparam TX_FIFO_THRESHOLD_REG_OFFSET = 16'hFE14;
    localparam TX_FIFO_FLUSH_REG_OFFSET = 16'hFE18;
    localparam IM_REG_OFFSET = 16'hFF00;
    localparam MIS_REG_OFFSET = 16'hFF04;
    localparam RIS_REG_OFFSET = 16'hFF08;
    localparam IC_REG_OFFSET = 16'hFF0C;
    localparam GCLK_REG_OFFSET = 16'hFF10;

    reg [0:0] GCLK_REG;
    wire clk = PCLK;
    wire rst_n = PRESETn;

    wire apb_valid = PSEL & PENABLE;
    wire apb_we = PWRITE & apb_valid;
    wire apb_re = ~PWRITE & apb_valid;

    wire [15:0] prescaler;
    wire en;
    wire tx_en;
    wire rx_en;
    wire [MDW-1:0] wdata;
    wire [5:0] timeout_bits;
    wire loopback_en;
    wire glitch_filter_en;
    wire [FAW-1:0] tx_level;
    wire [FAW-1:0] rx_level;
    wire rd;
    wire wr;
    wire tx_fifo_flush;
    wire rx_fifo_flush;
    wire [3:0] data_size;
    wire stop_bits_count;
    wire [2:0] parity_type;
    wire [FAW-1:0] txfifotr;
    wire [FAW-1:0] rxfifotr;
    wire [MDW-1:0] match_data;
    wire tx_empty;
    wire tx_full;
    wire tx_level_below;
    wire [MDW-1:0] rdata;
    wire rx_empty;
    wire rx_full;
    wire rx_level_above;
    wire break_flag;
    wire match_flag;
    wire frame_error_flag;
    wire parity_error_flag;
    wire overrun_flag;
    wire timeout_flag;

    reg [15:0] PR_REG;
    assign prescaler = PR_REG;
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) PR_REG <= 0;
        else if(apb_we & (PADDR[15:0] == PR_REG_OFFSET))
            PR_REG <= PWDATA[15:0];

    reg [4:0] CTRL_REG;
    assign en = CTRL_REG[0];
    assign tx_en = CTRL_REG[1];
    assign rx_en = CTRL_REG[2];
    assign loopback_en = CTRL_REG[3];
    assign glitch_filter_en = CTRL_REG[4];
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) CTRL_REG <= 0;
        else if(apb_we & (PADDR[15:0] == CTRL_REG_OFFSET))
            CTRL_REG <= PWDATA[4:0];

    reg [13:0] CFG_REG;
    assign data_size = CFG_REG[3:0];
    assign stop_bits_count = CFG_REG[4];
    assign parity_type = CFG_REG[7:5];
    assign timeout_bits = CFG_REG[13:8];
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) CFG_REG <= 14'h3F08;
        else if(apb_we & (PADDR[15:0] == CFG_REG_OFFSET))
            CFG_REG <= PWDATA[13:0];

    reg [MDW-1:0] MATCH_REG;
    assign match_data = MATCH_REG;
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) MATCH_REG <= 0;
        else if(apb_we & (PADDR[15:0] == MATCH_REG_OFFSET))
            MATCH_REG <= PWDATA[MDW-1:0];

    reg [FAW-1:0] RX_FIFO_THRESHOLD_REG;
    assign rxfifotr = RX_FIFO_THRESHOLD_REG;
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) RX_FIFO_THRESHOLD_REG <= 0;
        else if(apb_we & (PADDR[15:0] == RX_FIFO_THRESHOLD_REG_OFFSET))
            RX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];

    reg RX_FIFO_FLUSH_REG;
    assign rx_fifo_flush = RX_FIFO_FLUSH_REG;
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) RX_FIFO_FLUSH_REG <= 0;
        else if(apb_we & (PADDR[15:0] == RX_FIFO_FLUSH_REG_OFFSET))
            RX_FIFO_FLUSH_REG <= PWDATA[0];
        else
            RX_FIFO_FLUSH_REG <= 1'b0;

    reg [FAW-1:0] TX_FIFO_THRESHOLD_REG;
    assign txfifotr = TX_FIFO_THRESHOLD_REG;
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) TX_FIFO_THRESHOLD_REG <= 0;
        else if(apb_we & (PADDR[15:0] == TX_FIFO_THRESHOLD_REG_OFFSET))
            TX_FIFO_THRESHOLD_REG <= PWDATA[FAW-1:0];

    reg TX_FIFO_FLUSH_REG;
    assign tx_fifo_flush = TX_FIFO_FLUSH_REG;
    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) TX_FIFO_FLUSH_REG <= 0;
        else if(apb_we & (PADDR[15:0] == TX_FIFO_FLUSH_REG_OFFSET))
            TX_FIFO_FLUSH_REG <= PWDATA[0];
        else
            TX_FIFO_FLUSH_REG <= 1'b0;

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) GCLK_REG <= 0;
        else if(apb_we & (PADDR[15:0] == GCLK_REG_OFFSET))
            GCLK_REG <= PWDATA[0];

    reg [9:0] IM_REG;
    reg [9:0] IC_REG;
    reg [9:0] RIS_REG;

    wire [9:0] MIS_REG = RIS_REG & IM_REG;

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) IM_REG <= 0;
        else if(apb_we & (PADDR[15:0] == IM_REG_OFFSET))
            IM_REG <= PWDATA[9:0];

    always @(posedge PCLK or negedge PRESETn)
        if(!PRESETn) IC_REG <= 10'b0;
        else if(apb_we & (PADDR[15:0] == IC_REG_OFFSET))
            IC_REG <= PWDATA[9:0];
        else
            IC_REG <= 10'd0;

    wire [9:0] irq_conditions = {
        timeout_flag,
        overrun_flag,
        parity_error_flag,
        frame_error_flag,
        match_flag,
        break_flag,
        rx_level_above,
        tx_level_below,
        rx_full,
        tx_empty
    };

    integer i;
    always @(posedge PCLK or negedge PRESETn) begin
        if(!PRESETn)
            RIS_REG <= 10'b0;
        else
            for(i = 0; i < 10; i = i + 1) begin
                if(IC_REG[i])
                    RIS_REG[i] <= 1'b0;
                else if(irq_conditions[i])
                    RIS_REG[i] <= 1'b1;
            end
    end

    assign IRQ = |MIS_REG;

    EF_UART #(
        .SC(SC),
        .MDW(MDW),
        .GFLEN(GFLEN),
        .FAW(FAW)
    ) instance_to_wrap (
        .clk(clk),
        .rst_n(rst_n),
        .prescaler(prescaler),
        .en(en),
        .tx_en(tx_en),
        .rx_en(rx_en),
        .wdata(wdata),
