    wire        tmr_eq_reload_m_1   = (tmr == (tmr_reload - 1'b1));
    wire        tmr_eq_one          = (tmr == 1);
    wire        tmr_eq_cmpx         = (tmr == cmpx);
    wire        tmr_eq_cmpy         = (tmr == cmpy);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_run <= 1'b0;
        else if (tmr_en_pulse)
            tmr_run <= 1'b1;
        else if (!tmr_periodic && tick && tmr_mode[0] &&
                 tmr_eq_one && !tmr_dir)
            tmr_run <= 1'b0;
    end

    // The timer
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_reg <= 32'b0;
        else if (tmr_en_pulse) begin
            if (tmr_mode == 2'b01)
                tmr_reg <= tmr_reload;
            else
                tmr_reg <= 32'b0;
        end else if (tmr_en && tick && tmr_run) begin
            if (tmr_start && (tmr_mode == 2'b01))
                tmr_reg <= tmr_reload;
            else if (tmr_start &&
                     ((tmr_mode == 2'b10) || (tmr_mode == 2'b11)))
                tmr_reg <= 32'b0;
            else if (tmr_mode == 2'b11) begin
                if (tmr_dir)
                    tmr_reg <= tmr_reg + 1'b1;
                else
                    tmr_reg <= tmr_reg - 1'b1;
            end else if (tmr_mode == 2'b01) begin
                if (tmr_eq_zero) begin
                    if (tmr_periodic)
                        tmr_reg <= tmr_reload;
                end else
                    tmr_reg <= tmr_reg - 1'b1;
            end else if (tmr_mode == 2'b10) begin
                if (tmr_eq_reload) begin
                    if (tmr_periodic)
                        tmr_reg <= 32'b0;
                end else
                    tmr_reg <= tmr_reg + 1'b1;
            end
        end
