    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            tmr_dir <= 1'b1;
        else if (tmr_en_pulse) begin
            if (tmr_mode == 2'b01)
                tmr_dir <= 1'b0;
            else
                tmr_dir <= 1'b1;
        end else if (tick) begin
            if (tmr_mode == 2'b11) begin
                if (tmr_eq_reload_m_1 && tmr_dir)
                    tmr_dir <= 1'b0;
                else if (tmr_eq_one && !tmr_dir)
                    tmr_dir <= 1'b1;
            end else if (tmr_mode == 2'b10)
                tmr_dir <= 1'b1;
            else if (tmr_mode == 2'b01)
