    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pwm0_reg <= 0;
        else if (pwm0_en & tick)
            if (pwm_fault)
                pwm0_reg <= 0;
            else
                pwm0_reg <= pwm0_reg_next;

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pwm1_reg <= 0;
        else if (pwm1_en & tick)
            if (pwm_fault)
                pwm1_reg <= 0;
            else
                pwm1_reg <= pwm1_reg_next;

    // Dead time insertion
    reg pwm0_delayed;
    reg [7:0] dly_cntr;
    always @(posedge clk, negedge rst_n)
        if (!rst_n)
