                dly_cntr <= pwm_dt;
            else
                dly_cntr <= dly_cntr - 1;

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pwm0_delayed <= 0;
        else if (tick)
            if (dly_cntr == 0)
                pwm0_delayed <= pwm0_reg;

    reg pwm0_w_dt, pwm1_w_dt;
    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pwm0_w_dt <= 0;
        else
