            if (tmr_start && (tmr_mode == 2'b01))
                tmr_reg <= tmr_reload;
            else if (tmr_start && ((tmr_mode == 2'b10) ||
                                   (tmr_mode == 2'b11)))
                tmr_reg <= 0;
            else if (tmr_mode == 2'b01 && tmr_eq_zero)
                tmr_reg <= tmr_periodic ? tmr_reload : tmr_reg;
            else if (tmr_mode == 2'b10 && tmr_eq_reload)
