  always @(posedge PCLK or negedge PRESETn)
    if (~PRESETn) RIS_REG <= 10'b0;
    else begin
      for (i = 0; i < 10; i = i + 1) begin
        if (IC_REG[i])
          RIS_REG[i] <= 1'b0;
        else if (irq_sources[i])
          RIS_REG[i] <= 1'b1;
