module ef_util_sync #(parameter NUM_STAGES = 2) (
    input wire clk,
    input wire in,
    output wire out
);
    reg [NUM_STAGES-1:0] sync;
    always @(posedge clk)
        sync <= {sync[NUM_STAGES-2:0], in};
    assign out = sync[NUM_STAGES-1];
endmodule

module ef_util_ticker #(parameter W=8) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [W-1:0] clk_div,
    output wire tick
);
    reg [W-1:0] counter;
    wire counter_is_zero = (counter == 'b0);
    wire tick_w;
    reg tick_reg;

    always @(posedge clk or negedge rst_n)
        if (!rst_n)
            counter <= 'b0;
        else if (en)
            if (counter_is_zero)
                counter <= clk_div;
            else
                counter <= counter - 'b1;

    assign tick_w = (clk_div == 'b0) ? 1'b1 : counter_is_zero;

    always @(posedge clk or negedge rst_n)
        if (!rst_n)
            tick_reg <= 1'b0;
        else if (en)
            tick_reg <= tick_w;
        else
            tick_reg <= 1'b0;

    assign tick = tick_reg;
endmodule

module ef_util_glitch_filter #(parameter N = 8, CLKDIV = 8'd1) (
    input wire clk,
    input wire rst_n,
    input wire in,
    input wire en,
    output reg out
);
    reg [N-1:0] shifter;
    wire tick;

    ef_util_ticker ticker (
        .clk(clk),
        .rst_n(rst_n),
        .en(en),
        .clk_div(CLKDIV),
        .tick(tick)
    );

    always @(posedge clk or negedge rst_n)
        if (!rst_n)
            shifter <= 'b0;
        else if (tick)
            shifter <= {shifter[N-2:0], in};

    wire all_ones = &shifter;
    wire all_zeros = ~|shifter;

    always @(posedge clk or negedge rst_n)
        if (!rst_n)
            out <= 1'b0;
        else if (all_ones)
            out <= 1'b1;
        else if (all_zeros)
            out <= 1'b0;
endmodule

module ef_util_fifo #(parameter DW=8, AW=4) (
    input wire clk,
    input wire rst_n,
    input wire rd,
    input wire wr,
    input wire flush,
    input wire [DW-1:0] wdata,
    output wire empty,
    output wire full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 2**AW;

    reg [DW-1:0] array_reg [DEPTH-1:0];
    reg [AW-1:0] w_ptr_reg, w_ptr_next, w_ptr_succ;
    reg [AW-1:0] r_ptr_reg, r_ptr_next, r_ptr_succ;
    reg [AW-1:0] level_reg, level_next;
    reg full_reg, empty_reg, full_next, empty_next;
    wire w_en;

    always @(posedge clk)
        if (w_en)
            array_reg[w_ptr_reg] <= wdata;

    assign rdata = array_reg[r_ptr_reg];
    assign w_en = wr & ~full_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            w_ptr_reg <= 'b0;
            r_ptr_reg <= 'b0;
            full_reg <= 1'b0;
            empty_reg <= 1'b1;
            level_reg <= 'd0;
        end else if (flush) begin
            w_ptr_reg <= 'b0;
            r_ptr_reg <= 'b0;
            full_reg <= 1'b0;
            empty_reg <= 1'b1;
            level_reg <= 'd0;
        end else begin
            w_ptr_reg <= w_ptr_next;
            r_ptr_reg <= r_ptr_next;
            full_reg <= full_next;
            empty_reg <= empty_next;
            level_reg <= level_next;
        end
    end

    always @* begin
        w_ptr_succ = w_ptr_reg + 1'b1;
        r_ptr_succ = r_ptr_reg + 1'b1;
        w_ptr_next = w_ptr_reg;
        r_ptr_next = r_ptr_reg;
        full_next = full_reg;
        empty_next = empty_reg;
        level_next = level_reg;

        case ({w_en, rd})
            2'b01:
                if (!empty_reg) begin
                    r_ptr_next = r_ptr_succ;
                    full_next = 1'b0;
                    level_next = level_reg - 1'b1;
                    if (r_ptr_succ == w_ptr_reg)
                        empty_next = 1'b1;
                end
            2'b10:
                if (!full_reg) begin
                    w_ptr_next = w_ptr_succ;
                    empty_next = 1'b0;
                    level_next = level_reg + 1'b1;
                    if (w_ptr_succ == r_ptr_reg)
                        full_next = 1'b1;
                end
            2'b11: begin
                w_ptr_next = w_ptr_succ;
                r_ptr_next = r_ptr_succ;
            end
            default: begin
            end
        endcase
    end

    assign full = full_reg;
    assign empty = empty_reg;
    assign level = level_reg;
endmodule

