// From efabless/EF_IP_UTIL hdl/ef_util_lib.v (commit a2b3fb6): the modules EF_UART needs.
module ef_util_sync #(parameter NUM_STAGES = 2) (
    input wire clk,
    input wire in,
    output wire out
);

    reg [NUM_STAGES-1:0] sync;

    always @(posedge clk)
        sync <= {sync[NUM_STAGES-2:0], in};

    assign out = sync[NUM_STAGES-1];

endmodule

module ef_util_ticker #(parameter W=8) (
    input   wire            clk, 
    input   wire            rst_n,
    input   wire            en,
    input   wire [W-1:0]    clk_div,
    output  wire            tick
);

    reg [W-1:0] counter;
    reg         tick_reg;
    wire        counter_is_zero = (counter == 'b0);

    always @(posedge clk or negedge rst_n)
        if (!rst_n) begin
            counter <= 'b0;
            tick_reg <= 1'b0;
        end else begin
            if (en) begin
                if (counter_is_zero)
                    counter <= clk_div;
                else
                    counter <= counter - 1'b1;
                tick_reg <= counter_is_zero;
            end else begin
                tick_reg <= 1'b0;
            end
        end

    assign tick = tick_reg;

endmodule

module ef_util_glitch_filter #(parameter N = 8, CLKDIV = 8'd1) (
    input   wire    clk,
    input   wire    rst_n,
    input   wire    in,
    input   wire    en,
    output  reg     out
);

    reg [N-1:0] shifter;
    wire        tick;

    ef_util_ticker ticker (
        .clk(clk),
        .rst_n(rst_n),
        .en(en),
        .clk_div(CLKDIV),
        .tick(tick)
    );

    always @(posedge clk, negedge rst_n)
        if(!rst_n)
            shifter <= 'b0;
        else if(tick)
            shifter <= {shifter[N-2:0], in};

    wire all_ones   = & shifter;
    wire all_zeros  = ~| shifter;

    always @(posedge clk, negedge rst_n)
        if(!rst_n)
            out <= 1'b0;
        else
            if(all_ones) 
                out <= 1'b1;
            else if(all_zeros) 
                out <= 1'b0;
endmodule

module ef_util_fifo #(parameter DW=8, AW=4)(
    input   wire            clk,
    input   wire            rst_n,
    input   wire            rd,
    input   wire            wr,
    input   wire            flush,
    input   wire [DW-1:0]   wdata,
    output  wire            empty,
    output  wire            full,
    output  wire [DW-1:0]   rdata,
    output  wire [AW-1:0]   level    
);

    localparam DEPTH = 2**AW;

    reg [DW-1:0] array_reg [DEPTH-1:0];
    reg [AW-1:0] w_ptr_reg;
    reg [AW-1:0] r_ptr_reg;
    reg [AW-1:0] level_reg;
    reg          full_reg;
    reg          empty_reg;

    wire w_en = wr & ~full_reg;
    wire [AW-1:0] w_ptr_succ = w_ptr_reg + 1'b1;
    wire [AW-1:0] r_ptr_succ = r_ptr_reg + 1'b1;

    always @(posedge clk)
        if (w_en && !flush)
            array_reg[w_ptr_reg] <= wdata;

    assign rdata = array_reg[r_ptr_reg];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            w_ptr_reg <= 'b0;
            r_ptr_reg <= 'b0;
            full_reg  <= 1'b0;
            empty_reg <= 1'b1;
            level_reg <= 'b0;
        end else if (flush) begin
            w_ptr_reg <= 'b0;
            r_ptr_reg <= 'b0;
            full_reg  <= 1'b0;
            empty_reg <= 1'b1;
            level_reg <= 'b0;
        end else begin
            case ({w_en, rd})
                2'b01: begin
                    if (!empty_reg) begin
                        r_ptr_reg <= r_ptr_succ;
                        full_reg  <= 1'b0;
                        level_reg <= level_reg - 1'b1;
                        if (r_ptr_succ == w_ptr_reg)
                            empty_reg <= 1'b1;
                    end
                end
                2'b10: begin
                    w_ptr_reg <= w_ptr_succ;
                    empty_reg <= 1'b0;
                    level_reg <= level_reg + 1'b1;
                    if (w_ptr_succ == r_ptr_reg)
                        full_reg <= 1'b1;
                end
                2'b11: begin
                    w_ptr_reg <= w_ptr_succ;
                    r_ptr_reg <= r_ptr_succ;
                end
                default: begin
                end
            endcase
        end
    end

    assign full  = full_reg;
    assign empty = empty_reg;
    assign level = level_reg;

endmodule

