    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            tmr_dir <= 1;
        else if (tmr_clr) begin
            if (tmr_mode == 2'b01)
                tmr_dir <= 0;
            else
                tmr_dir <= 1;
        end
        else if (tick)
            if (tmr_mode == 2'b11) begin
                if (tmr_eq_one && !tmr_dir)
                    tmr_dir <= 1;
                else if (tmr_eq_reload_m_1 && tmr_dir)
