    wire pwm_e1 = tmr_dir && tmr_eq_cmpx && !tmr_eq_zero && !tmr_eq_cmpy && !tmr_eq_reload;
    wire pwm_e2 = tmr_dir && tmr_eq_cmpy && !tmr_eq_zero && !tmr_eq_cmpx && !tmr_eq_reload;
    wire pwm_e3 = tmr_eq_reload && !tmr_eq_zero && !tmr_eq_cmpx && !tmr_eq_cmpy;
    wire pwm_e4 = !tmr_dir && tmr_eq_cmpy && !tmr_eq_zero && !tmr_eq_cmpx && !tmr_eq_reload;
