    reg     pwm1_reg, pwm1_reg_next;

    always @* begin
        pwm0_reg_next = pwm0_reg;
        case ({pwm_e5, pwm_e4, pwm_e3, pwm_e2, pwm_e1, pwm_e0})
            6'b000001: pwm0_reg_next = pwm_action(pwm0_cfg[1:0], pwm0_reg);
            6'b000010: pwm0_reg_next = pwm_action(pwm0_cfg[3:2], pwm0_reg);
            6'b000100: pwm0_reg_next = pwm_action(pwm0_cfg[5:4], pwm0_reg);
            6'b001000: pwm0_reg_next = pwm_action(pwm0_cfg[7:6], pwm0_reg);
            6'b010000: pwm0_reg_next = pwm_action(pwm0_cfg[9:8], pwm0_reg);
            6'b100000: pwm0_reg_next = pwm_action(pwm0_cfg[11:10], pwm0_reg);
            default:   pwm0_reg_next = pwm0_reg;
        endcase
    end

    always @* begin
        pwm1_reg_next = pwm1_reg;
        case ({pwm_e5, pwm_e4, pwm_e3, pwm_e2, pwm_e1, pwm_e0})
            6'b000001: pwm1_reg_next = pwm_action(pwm1_cfg[1:0], pwm1_reg);
            6'b000010: pwm1_reg_next = pwm_action(pwm1_cfg[3:2], pwm1_reg);
            6'b000100: pwm1_reg_next = pwm_action(pwm1_cfg[5:4], pwm1_reg);
            6'b001000: pwm1_reg_next = pwm_action(pwm1_cfg[7:6], pwm1_reg);
            6'b010000: pwm1_reg_next = pwm_action(pwm1_cfg[9:8], pwm1_reg);
            6'b100000: pwm1_reg_next = pwm_action(pwm1_cfg[11:10], pwm1_reg);
            default:   pwm1_reg_next = pwm1_reg;
        endcase
    end

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pwm0_reg <= 0;
        else if (pwm0_en && tick)
            if (pwm_fault)
                pwm0_reg <= 0;
            else
                pwm0_reg <= pwm0_reg_next;

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pwm1_reg <= 0;
        else if (pwm1_en && tick)
            if (pwm_fault)
                pwm1_reg <= 0;
            else
                pwm1_reg <= pwm1_reg_next;

    // Dead time insertion
