                    tmr_reg <= tmr_reg;
                end else if (tmr_start) begin
                    tmr_reg <= tmr_reg;
                end else if (tmr_start) begin
                    tmr_reg <= tmr_reg;
                end else if (tmr_start) begin
                    tmr_reg <= tmr_reg;
                end else if (tmr_start) begin
                    tmr_reg <= tmr_reg;
                end else if (tmr_start) begin
