    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pr_reg <= 1;
        else if (tmr_en) begin
            if (tick)
                pr_reg <= prescaler;
            else
                pr_reg <= pr_reg - 1'b1;
        end else begin
            pr_reg <= prescaler;
        end

    reg         tmr_dir;        // 1: Up, 0: Down
    wire        tmr_eq_reload       = (tmr == tmr_reload);
    wire        tmr_eq_zero         = (tmr == 0);
    wire        tmr_eq_reload_m_1   = (tmr == (tmr_reload - 1'b1));
    wire        tmr_eq_one          = (tmr == 1);
    wire        tmr_eq_cmpx         = (tmr == cmpx);
    wire        tmr_eq_cmpy         = (tmr == cmpy);

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            tmr_run <= 1'b0;
        else if (tmr_en_pulse)
            tmr_run <= 1'b1;
        else if (!tmr_periodic && tick &&
                 tmr_mode[0] && tmr_eq_one && !tmr_dir)
            tmr_run <= 1'b0;

    // The timer
    reg [31:0] tmr_reg_next;

    always @* begin
        tmr_reg_next = tmr_reg;

        if (tmr_start && tmr_mode == 2'b01) begin
            tmr_reg_next = tmr_reload;
        end else if (tmr_start &&
                     (tmr_mode == 2'b10 || tmr_mode == 2'b11)) begin
            tmr_reg_next = 32'b0;
        end else if (tmr_start) begin
            tmr_reg_next = tmr_reg;
        end else if (tmr_mode == 2'b11) begin
            if (tmr_dir)
                tmr_reg_next = tmr_reg + 1'b1;
            else
                tmr_reg_next = tmr_reg - 1'b1;
        end else if (tmr_mode == 2'b01) begin
            if (tmr_eq_zero)
                tmr_reg_next = tmr_periodic ? tmr_reload : tmr_reg;
            else
                tmr_reg_next = tmr_reg - 1'b1;
        end else if (tmr_mode == 2'b10) begin
            if (tmr_eq_reload)
                tmr_reg_next = tmr_periodic ? 32'b0 : tmr_reg;
            else
                tmr_reg_next = tmr_reg + 1'b1;
        end
    end

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            tmr_reg <= 32'b0;
        else if (tmr_en) begin
            if (tmr_clr) begin
                if (tmr_mode == 2'b01)
                    tmr_reg <= tmr_reload;
                else
                    tmr_reg <= 32'b0;
            end else if (tmr_run && tick) begin
                if (tmr_start && tmr_mode == 2'b01)
                    tmr_reg <= tmr_reload;
                else if (tmr_start &&
                         (tmr_mode == 2'b10 || tmr_mode == 2'b11))
                    tmr_reg <= 32'b0;
                else if (tmr_start)
                    tmr_reg <= tmr_reg;
                else if (tmr_start) begin
                    tmr_reg <= tmr_reg;
                end else if (tmr_start) begin
                    tmr_reg <= tmr_reg;
                end else if (tmr_start) begin
                    tmr_reg <= tmr_reg;
                end else if (tmr_start) begin
                    tmr_reg <= tmr_reg;
                end else if (tmr_start) begin
                    tmr_reg <= tmr_reg;
                end else if (tmr_start) begin
                    tmr_reg <= tmr_reg;
                end else if (tmr_start) begin
                    tmr_reg <= tmr_reg;
                end else begin
                    tmr_reg <= tmr_reg_next;
