  input         PSEL,
  input         PENABLE,
  input         PWRITE,
  input  [7:0]  PADDR,
  input  [31:0] PWDATA,
  output [31:0] PRDATA,
  output        PREADY,
  output        PSLVERR,
  output        wr_en,
  output        rd_en,
  output [7:0]  addr,
  output [31:0] wdata,
  input  [31:0] rdata,
  input         err
);
  wire access = PSEL && PENABLE;

  assign wr_en   = access && PWRITE;
  assign rd_en   = access && !PWRITE;
  assign addr    = PADDR;
  assign wdata   = PWDATA;
  assign PREADY  = 1'b1;
  assign PSLVERR = access && err;
  assign PRDATA  = (rd_en && !err) ? rdata : 32'b0;
