  input  [31:0]                      PWDATA,
  output [31:0]                      PRDATA,
  output                             PREADY,
  output                             PSLVERR,
  input  [NUM_SRC-1:0]               irq_src,
  output                             irq,
  output [$clog2(NUM_SRC+1)-1:0]     irq_id
);
