  wire                     wr_en, rd_en, err;
  wire [7:0]               addr;
  wire [31:0]              wdata, rdata;
  wire                     gen;
  wire [NUM_SRC-1:0]       enable, trigger, in_service, pending, src_sync, clear_mask, force_mask;
  wire [PRIO_BITS-1:0]     threshold, best_prio;
  wire [NUM_SRC*PRIO_BITS-1:0] prio_flat;
