                    | (claim ? ({{(NUM_SRC-1){1'b0}}, 1'b1} << (irq_id - 1)) : {NUM_SRC{1'b0}});
  assign force_mask = (do_write && addr == A_FORCE) ? wdata[NUM_SRC-1:0] : {NUM_SRC{1'b0}};

