module intc_pending #(
  parameter N = 8
) (
  input              clk,
  input              rst,
  input      [N-1:0] src,
  input      [N-1:0] trigger,
  input      [N-1:0] clear_mask,
  input      [N-1:0] force_mask,
  output reg [N-1:0] pending
