                tx_next = 1'b0;
                case (parity_type)
                    3'b001 :
                        tx_next = ~^pdata;
                    3'b010 :
                        tx_next = ^pdata;
                    3'b100 :
                        tx_next = 0;
                    3'b101 :
                        tx_next = 1;
                endcase
