  output [31:0] PRDATA,
  output        PREADY,
  output        PSLVERR,
  output        wr_en,
  output        rd_en,
  output [7:0]  addr,
  output [31:0] wdata,
  input  [31:0] rdata,
  input         err
);
  wire access = PSEL && PENABLE;

