            (PADDR[16-1:0] == TX_FIFO_FLUSH_REG_OFFSET)    ? TX_FIFO_FLUSH_REG :
            (PADDR[16-1:0] == IM_REG_OFFSET)               ? IM_REG :
            (PADDR[16-1:0] == MIS_REG_OFFSET)              ? MIS_REG :
